// Pronouns Page JavaScript
(function() {
    'use strict';

    function pronounceName() {
        if ('speechSynthesis' in window) {
            const utterance = new SpeechSynthesisUtterance('Zahara Schaefer');
            utterance.lang = 'en-US';
            utterance.rate = 0.8;
            speechSynthesis.speak(utterance);
        } else {
            alert('Text-to-speech is not supported in your browser.');
        }
    }

    // Initialize when DOM is ready
    document.addEventListener('DOMContentLoaded', function() {
        // Make pronounceName function globally available for onclick handler
        window.pronounceName = pronounceName;
    });
})();

